package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.InventoryDtos.MaterialRequest; import com.vynedam.stockai.model.Material; import com.vynedam.stockai.service.MaterialService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/materials") public class MaterialController { private final MaterialService service; public MaterialController(MaterialService s){service=s;} @GetMapping List<Material> list(){return service.list();}@GetMapping("/{id}") Material get(@PathVariable String id){return service.get(id);}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','PURCHASE_MANAGER')") ResponseEntity<Material> create(@Valid @RequestBody MaterialRequest r){return ResponseEntity.status(201).body(service.create(r));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','PURCHASE_MANAGER')") Material update(@PathVariable String id,@Valid @RequestBody MaterialRequest r){return service.update(id,r);} }
